const { model, ratio, size } = $('Choose recipe and format').first().json;
const { models, error } = $input.first().json;

if (![model, ratio, size].every(value => typeof value === 'string' && value.trim())) {
  return [{ json: { decision: 'INVALID_REQUEST' } }];
}

const observation = models && Object.hasOwn(models, model) ? models[model] : null;
const checkedAt = observation?.checked_at;
const now = Date.now() / 1000;
const fresh = Number.isFinite(checkedAt) && checkedAt > 0 &&
  checkedAt >= now - 120 && checkedAt <= now + 60;

let decision = 'WAIT_UNVERIFIED';
if (!error && fresh) {
  if (observation.generation_status === 'unavailable') {
    decision = 'WAIT_CAPACITY';
  } else if (observation.generation_status === 'available') {
    const formats = observation.available_formats;
    const exact = Array.isArray(formats) &&
      formats.some(format => format?.ratio === ratio && format?.size === size);
    decision = exact ? 'REVIEW_FUNDING' : 'WAIT_FORMAT';
  }
}

return [{ json: { model, ratio, size, checkedAt: fresh ? checkedAt : null, decision } }];
